data: {"id":"chatcmpl-20261018180146279470637c955d568XywgpA1I","created":1792346506,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_3ffe0bad3c9248d582b72044","index":0,"type":"function","function":{"name":"file_write","arguments":"{\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"\\nmetrics_demo.py — DEMO ONLY: synthetic evaluation of forecast-verification metrics.\\n\\nNOT real forecast skill. Outcomes are simulated with a fixed seed; this verifies\\nthe scoring pipeline and illustrates metric behavior under known miscalibrations.\\nThe real London 2026-10-19 outcome has not occurred and is not used anywhere here.\\n\\nSeed: 20261019 (reproducible). Pure stdlib (statistics.NormalDist).\\n\\\"\\\"\\\"\\nimport json, math, random, statistics\\nfrom statistics import NormalDist\\n\\nSTD = NormalDist()\\nSEED = 20261019\\nN = 30\\nMU_CLIM, SIG_CLIM = 11.5, 3.0   # illustrative climatology prior: London mid-Oct daily mean\\n\\n\\ndef crps_normal(mu, sigma, y):\\n    \\\"\\\"\\\"Closed-form CRPS for a Gaussian predictive (Gneiting et al. 2005).\\\"\\\"\\\"\\n    z = (y - mu) / sigma\\n    return sigma * (z * (2 * STD.cdf(z) - 1) + 2 * STD.pdf(z) - 1 / math.sqrt(math.pi))\\n\\n\\ndef central(mu, sigma, level):\\n    a = (1 - level) / 2\\n    return mu + sigma * STD.inv_cdf(a), mu + sigma * STD.inv_cdf(1 - a)\\n\\n\\ndef evaluate(pairs, ref_mu=MU_CLIM, ref_sig=SIG_CLIM):\\n    \\\"\\\"\\\"pairs: list of (mu, sigma, y). Reference = climatology N(11.5, 3).\\\"\\\"\\\"\\n    errs = [y - mu for mu, _, y in pairs]\\n    crps = [crps_normal(mu, sig, y) for mu, sig, y in pairs]\\n    ref_crps = [crps_normal(ref_mu, ref_sig, y) for _, _, y in pairs]\\n    n = len(pairs)\\n    mcrps = sum(crps) / n\\n    cov, wid = {}, {}\\n    for lv in (0.5, 0.8, 0.95):\\n        hits = wsum = 0.0\\n        for mu, sig, y in pairs:\\n            lo, hi = central(mu, sig, lv)\\n            hits += lo <= y <= hi\\n            wsum += hi - lo\\n        cov[lv], wid[lv] = hits / n, wsum / n\\n    pits = sorted(STD.cdf((y - mu) / sig) for mu, sig, y in pairs)\\n    bins = [0] * 5\\n    for p in pits:\\n        bins[min(4, int(p * 5))] += 1\\n    return {\\n        \\\"n\\\": n,\\n        \\\"bias\\\": round(sum(errs) / n, 3),\\n        \\\"MAE\\\": round(sum(abs(e) for e in errs) / n, 3),\\n        \\\"RMSE\\\": round(math.sqrt(sum(e * e for e in errs) / n), 3),\\n        \\\"CRPS_mean\\\": round(mcrps, 3),\\n        \\\"CRPS_skill_vs_clim\\\": round(1 - mcrps / (sum(ref_crps) / n), 3),\\n        \\\"coverage_50\\\": cov[0.5], \\\"coverage_80\\\": cov[0.8], \\\"coverage_95\\\": cov[0.95],\\n        \\\"width_50\\\": round(wid[0.5], 2), \\\"width_80\\\": round(wid[0.8], 2),\\n        \\\"PIT_mean\\\": round(sum(pits) / n, 3),\\n        \\\"PIT_sd\\\": round(statistics.pstdev(pits), 3),\\n        \\\"PIT_bins_5\\\": bins,\\n    }\\n\\n\\nrng = random.Random(SEED)\\n\\n# Shared synthetic outcome vector for A/B/C (one truth, three predictive specs)\\ny = [rng.gauss(MU_CLIM, SIG_CLIM) for _ in range(N)]\\nA = [(MU_CLIM, SIG_CLIM, yi) for yi in y]      # calibrated control (= climatology)\\nB = [(MU_CLIM, 1.8, yi) for yi in y]           # overconfident: sigma 1.8 vs true 3.0\\nC = [(13.0, 2.5, yi) for yi in y]              # warm-biased center (+1.5)\\n\\n# D: persistence recipe on synthetic AR(1) weather, phi=0.7, stationary sd 3.0\\nphi = 0.7\\neps_sd = SIG_CLIM * math.sqrt(1 - phi ** 2)    # residual sd = 2.1424\\nx = MU_CLIM\\nD = []\\nfor _ in range(N):\\n    mu_hat = MU_CLIM + phi * (x - MU_CLIM)     # optimal lag-1 predictor\\n    x = MU_CLIM + phi * (x - MU_CLIM) + rng.gauss(0, eps_sd)\\n    D.append((mu_hat, eps_sd, x))\\n\\nresults = {\\n    \\\"_meta\\\": {\\n        \\\"label\\\": \\\"SYNTHETIC DEMO — pipeline verification, NOT real forecast skill\\\",\\n        \\\"seed\\\": SEED,\\n        \\\"n_per_variant\\\": N,\\n        \\\"outcome_model\\\": \\\"A/B/C: y ~ N(11.5, 3.0); D: AR(1) phi=0.7, stationary sd 3.0\\\",\\n        \\\"reference\\\": \\\"climatology N(11.5, 3.0)\\\",\\n        \\\"uniform_PIT_sd_expected\\\": round(1 / math.sqrt(12), 3),\\n    },\\n    \\\"A_calibrated_control\\\": evaluate(A),\\n    \\\"B_overconfident\\\": evaluate(B),\\n    \\\"C_warm_biased\\\": evaluate(C),\\n    \\\"D_persistence_AR1\\\": evaluate(D),\\n}\\n\\nwith open(\\\"backtest_demo/results.json\\\", \\\"w\\\") as f:\\n    json.dump(results, f, indent=2)\\n\\nfor k, v in results.items():\\n    print(k, \\\":\\\", json.dumps(v) if isinstance(v, dict) else v)\\n\",\"path\":\"backtest_demo/metrics_demo.py\"}"}}]}}]}

